import { DatabaseSync } from "node:sqlite";
import { readFileSync } from "node:fs";
import { beforeEach, afterEach, describe, expect, it, vi } from "vitest";
import { VERSION, newOrder } from "../../store-orders/core.js";
vi.mock("../worker/src/access",()=>({verifyCompanyUser:vi.fn(async r=>r.headers.get("X-Test-Email") || Promise.reject(new Response("需要公司登入",{status:401})))}));
import { storeOrdersRoute, OrderDrive } from "../worker/src/store-orders";
const EMAIL="store@siangapato.com.tw",HQ="hq@siangapato.com.tw",OTHER="other@siangapato.com.tw";
const config={sharedDriveId:"shared-drive-001",settledFolderId:"settled-folder-001",recycleFolderId:"recycle-folder-001",hqEmails:[HQ],stores:{R00:{pendingFolderId:"pending-folder-001",emails:[EMAIL]},R01:{pendingFolderId:"pending-folder-002",emails:[OTHER]}}};
let sql,env,files,serial;
function database(){return {prepare(query){let args=[];return {bind(...values){args=values;return this;},async first(){return sql.prepare(query).get(...args)||null;},async all(){return {results:sql.prepare(query).all(...args)};},async run(){const r=sql.prepare(query).run(...args);return {success:true,meta:{changes:Number(r.changes)}};}};},async batch(statements){sql.exec("BEGIN");try{const rs=[];for(const s of statements)rs.push(await s.run());sql.exec("COMMIT");return rs;}catch(e){sql.exec("ROLLBACK");throw e;}}};}
function file(id,folder,content,mime="application/json",extra={}){files.set(id,{id,parents:[folder],driveId:config.sharedDriveId,mimeType:mime,content,appProperties:{},...extra});}
async function call(path,body,email=EMAIL,extra={}){const r=await storeOrdersRoute(new Request(`https://siangstock.com/api/store-orders${path}`,{method:body===undefined?"GET":"POST",headers:{Origin:"https://siangstock.com","Content-Type":"application/json","X-Store-Orders-Version":VERSION,"X-Test-Email":email,...extra},...(body===undefined?{}:{body:JSON.stringify(body)})}),env);return {status:r.status,body:await r.json()};}
function order(){const o=newOrder("test-order-001","R00","2026-10-23");Object.assign(o,{paperNumber:"SYNTH-001",clerk:"合成經手人",status:"reviewed",reviewed:true,paperTotal:250,paperRowCount:2,sources:[{fileId:"source-file-001",pages:1,verified:true}],masterVersion:"test"});o.items=[{sku:"00001",name:"合成商品",color:"白",size:"均碼",quantity:2,unitPrice:100,saleType:"銷貨",matchStatus:"unique"},{sku:"00002",name:"合成商品二",color:"藍",size:"均碼",quantity:1,unitPrice:50,saleType:"訂貨",matchStatus:"unique"}];o.customer={name:"不得入D1",phone:"0900000000",address:"不得入D1地址"};o.payments.現金=250;return o;}
async function register(){file("source-file-001",config.stores.R00.pendingFolderId,"synthetic-image","image/png");expect((await call("/sources",{storeCode:"R00",fileId:"source-file-001"})).status).toBe(200);}
async function save(o=order(),version=0,operationId=crypto.randomUUID()){return call("/orders",{order:o,expectedVersion:version,operationId});}
async function settled(){await register();expect((await save()).status).toBe(200);const r=await call("/settle",{storeCode:"R00",businessDate:"2026-10-23",orders:[{id:"test-order-001",version:1}],confirmed:true,operationId:crypto.randomUUID()});expect(r.status).toBe(200);return r;}
beforeEach(()=>{
 sql=new DatabaseSync(":memory:");sql.exec(readFileSync("worker/migrations/0042_store_orders.sql","utf8"));sql.exec(readFileSync("worker/migrations/0045_store_order_guests.sql","utf8"));sql.exec(readFileSync("worker/migrations/0047_store_order_invite_labels.sql","utf8"));sql.exec(readFileSync("worker/migrations/0044_store_order_recognition.sql","utf8"));sql.exec(readFileSync("worker/migrations/0052_store_order_source_removals.sql","utf8"));sql.exec(readFileSync("worker/migrations/0053_store_order_recognition_recovery.sql","utf8"));sql.exec(readFileSync("worker/migrations/0054_store_order_source_reconciliation.sql","utf8"));files=new Map();serial=0;
 env={DB:database(),ALLOWED_ORIGINS:"https://siangstock.com",STORE_ORDERS_CONFIG:JSON.stringify(config),STORE_ORDERS_SERVICE_ACCOUNT:JSON.stringify({client_email:"service@test.gserviceaccount.com",private_key:"test-not-a-key"}),ACCESS_AUD:"test",ACCESS_TEAM_DOMAIN:"test"};
 vi.spyOn(OrderDrive.prototype,"checkFolder").mockResolvedValue(undefined);vi.spyOn(OrderDrive.prototype,"checkPermissions").mockResolvedValue(undefined);
 vi.spyOn(OrderDrive.prototype,"meta").mockImplementation(async id=>{if(!files.has(id))throw Error("missing");const f=files.get(id);return {...f,size:String(JSON.stringify(f.content).length),md5Checksum:"stable-md5"};});
 vi.spyOn(OrderDrive.prototype,"sourceMeta").mockImplementation(async id=>files.has(id)?OrderDrive.prototype.meta(id):null);
 vi.spyOn(OrderDrive.prototype,"list").mockImplementation(async(folder,imagesOnly)=>[...files.values()].filter(f=>f.parents.includes(folder)&&(!imagesOnly||f.mimeType.startsWith("image/")||f.mimeType==="application/pdf")));
 vi.spyOn(OrderDrive.prototype,"read").mockImplementation(async id=>new TextEncoder().encode(typeof files.get(id).content==="string"?files.get(id).content:JSON.stringify(files.get(id).content)).buffer);
 vi.spyOn(OrderDrive.prototype,"json").mockImplementation(async id=>structuredClone(files.get(id).content));
 vi.spyOn(OrderDrive.prototype,"write").mockImplementation(async(folder,name,content,op)=>{const existing=[...files.values()].find(f=>f.parents.includes(folder)&&f.appProperties.soOperation===op);if(existing)return existing.id;const id=`snapshot-file-${++serial}`;file(id,folder,structuredClone(content),"application/json",{appProperties:{soOperation:op,soKind:"snapshot"}});return id;});
 vi.spyOn(OrderDrive.prototype,"move").mockImplementation(async(id,from,to)=>{const f=files.get(id);if(!f.parents.includes(from)&&!f.parents.includes(to))throw Error("wrong folder");f.parents=[to];});
});
afterEach(()=>{vi.restoreAllMocks();sql.close();});
describe("門市訂單API與真實SQLite交易",()=>{
 it("簡寫品名不阻擋；明顯類型矛盾須核對，API也不得繞過",async()=>{await register();const o=order();o.items[0].name="天絲床包組";o.items[0].paperName="床包";expect((await save(o)).status).toBe(200);o.version=1;o.items[0].paperName="枕頭";expect((await save(o,1)).status).toBe(400);o.items[0].nameHintAcknowledged=true;expect((await save(o,1)).status).toBe(200);const r=await call("/orders/test-order-001");expect(r.body.order.items[0].name).toBe("天絲床包組");expect(r.body.order.items[0].paperName).toBe("枕頭");});
 it("未設定雲端或未登入時fail closed",async()=>{const missing={...env,STORE_ORDERS_CONFIG:undefined};const r=await storeOrdersRoute(new Request("https://siangstock.com/api/store-orders/session"),missing);expect(r.status).toBe(503);const auth=await storeOrdersRoute(new Request("https://siangstock.com/api/store-orders/session"),env);expect(auth.status).toBe(401);});
 it("session只回本店；同公司未指派帳號仍拒絕",async()=>{const r=await call("/session");expect(Object.keys(r.body.stores)).toEqual(["R00"]);expect(r.body).not.toHaveProperty("private_key");expect((await call("/session",undefined,"unassigned@siangapato.com.tw")).status).toBe(403);});
 it("跨店讀寫與未授權來源、舊版本拒絕",async()=>{expect((await call("/queue?store=R01&date=2026-10-23")).status).toBe(403);expect((await call("/sources",{storeCode:"R01",fileId:"source-file-001"})).status).toBe(403);expect((await call("/sources",{},EMAIL,{Origin:"https://evil.example"})).status).toBe(403);expect((await call("/sources",{},EMAIL,{"X-Store-Orders-Version":"old"})).status).toBe(409);});
 it("完整未修改流程：收單→覆核→結算→HQ測試產檔→ERP完成；D1無個資或明細",async()=>{
  const r=await settled();expect(r.body.summary).toMatchObject({orders:1,rows:2,quantity:3,amountCents:25000});
  expect((await call("/orders/test-order-001")).status).toBe(403);
  const q=await call("/queue?store=R00&date=2026-10-23");expect(q.body.orders).toEqual([]);expect(q.body.batches).toHaveLength(1);
  const h=await call("/orders/test-order-001",undefined,HQ);expect(h.body.order.status).toBe("settled");expect(h.body.order.version).toBe(2);
  expect((await call("/orders/test-order-001/export",{expectedVersion:2,mode:"production"},HQ)).status).toBe(403);
  expect((await call("/orders/test-order-001/export",{expectedVersion:2,mode:"test"},HQ)).status).toBe(200);
  expect((await call("/orders/test-order-001/export",{expectedVersion:3,mode:"test"},HQ)).status).toBe(409);
  expect((await call("/orders/test-order-001/result",{expectedVersion:3,status:"erp_created",erpNumber:"ERP-0001",reason:"測試環境確認成功",operationId:crypto.randomUUID()},HQ)).status).toBe(410);
  const dumped=JSON.stringify(sql.prepare("SELECT * FROM store_orders").all())+JSON.stringify(sql.prepare("SELECT * FROM store_order_events").all());expect(dumped).not.toContain("不得入D1");expect(dumped).not.toContain("0900000000");expect(dumped).not.toContain("00002");
 });
 it("人工改量後再次覆核，總額與快照一致；舊版寫入拒絕",async()=>{await register();expect((await save()).status).toBe(200);const o=order();o.items[0].quantity=3;o.payments.現金=350;o.paperTotal=350;o.version=1;expect((await save(o,1)).status).toBe(200);expect((await save(o,1)).status).toBe(409);const loaded=await call("/orders/test-order-001");expect(loaded.body.order.items[0].quantity).toBe(3);});
 it("同操作重試不增加版本，換內容不能重用操作ID",async()=>{await register();const op=crypto.randomUUID(),o=order();expect((await save(o,0,op)).body.version).toBe(1);expect((await save(o,0,op)).body.version).toBe(1);o.paperTotal=0;o.status="pending";expect((await save(o,0,op)).status).toBe(409);});
 it("兩台裝置同時保存同來源，只能屬於一張訂單",async()=>{await register();expect((await save()).status).toBe(200);const second=order();second.id="test-order-002";second.paperNumber="SYNTH-002";expect((await save(second)).status).toBe(409);});
 it("同訂單兩台裝置同版本競爭，只有一次提交",async()=>{await register();const rs=await Promise.all([save(),save()]);expect(rs.map(r=>r.status).sort()).toEqual([200,409]);expect(sql.prepare("SELECT version FROM store_orders").get().version).toBe(1);});
 it("原始內容直接被Drive修改，不得當成已覆核資料",async()=>{await register();await save();const row=sql.prepare("SELECT drive_id FROM store_orders").get();files.get(row.drive_id).content.items[0].quantity=99;expect((await call("/orders/test-order-001")).status).toBe(409);});
 it("同紙本單號不同照片需明確阻擋，不悄悄建立第二單",async()=>{await register();await save();const second=order();second.id="test-order-002";expect((await save(second)).status).toBe(409);});
 it("結算前新圖未收單、過期清單、不完整覆核均阻擋",async()=>{await register();await save();file("source-file-new",config.stores.R00.pendingFolderId,"new-image","image/png");const b={storeCode:"R00",businessDate:"2026-10-23",orders:[{id:"test-order-001",version:1}],confirmed:true,operationId:crypto.randomUUID()};expect((await call("/settle",b)).status).toBe(409);expect(sql.prepare("SELECT status FROM store_orders").get().status).toBe("reviewed");});
 it("預檢發現新單時釋放準備鎖，允許補件保存，不會陷入結算死鎖",async()=>{await register();await save();file("source-file-new",config.stores.R00.pendingFolderId,"new-image","image/png");const b={storeCode:"R00",businessDate:"2026-10-23",orders:[{id:"test-order-001",version:1}],confirmed:true,operationId:crypto.randomUUID()};const result=await call("/settle",b);expect(result.body.code).toBe("settlement_reconfirm");expect(sql.prepare("SELECT status FROM store_order_batches").get().status).toBe("aborted");const o=order();o.version=1;expect((await save(o,1)).status).toBe(200);});
 it("未覆核空欄可暫存，不能被誤當已覆核結算",async()=>{const o=newOrder("empty-order-001","R00","2026-10-23");expect((await save(o)).status).toBe(200);const result=await call("/settle",{storeCode:"R00",businessDate:"2026-10-23",orders:[{id:o.id,version:1}],confirmed:true,operationId:crypto.randomUUID()});expect(result.status).toBe(400);expect(result.body.code).toBe("settlement_reconfirm");});
 it("90天回收只處理完成批次，未完成或未到期的不移動，不永久刪除",async()=>{await settled();await call("/orders/test-order-001/export",{expectedVersion:2,mode:"test"},HQ);sql.prepare("UPDATE store_orders SET status='erp_created',erp_created_at=?").run(new Date().toISOString());expect((await call("/retention",{},HQ)).body.recycledBatches).toBe(0);sql.prepare("UPDATE store_orders SET erp_created_at=?").run(new Date(Date.now()-91*86400000).toISOString());const result=await call("/retention",{},HQ);expect(result.body).toEqual({recycledBatches:1,permanentlyDeleted:false});expect(sql.prepare("SELECT recycled_at FROM store_orders").get().recycled_at).toBeTruthy();expect(files.get("source-file-001").parents).toEqual([config.recycleFolderId]);expect((await call("/orders/test-order-001",undefined,HQ)).status).toBe(410);});
 it("逾30天跨日期待辦限總部查看",async()=>{await register();await save();sql.prepare("UPDATE store_orders SET business_date='2020-01-01'").run();expect((await call("/attention")).status).toBe(403);expect((await call("/attention",undefined,HQ)).body.orders).toHaveLength(1);});
 it("交接中途失敗不提交；用原操作重試可完成且不重複批次",async()=>{
  await register();await save();const b={storeCode:"R00",businessDate:"2026-10-23",orders:[{id:"test-order-001",version:1}],confirmed:true,operationId:crypto.randomUUID()};
  const original=OrderDrive.prototype.move.getMockImplementation();let failed=false;OrderDrive.prototype.move.mockImplementation(async(...args)=>{if(!failed){failed=true;throw Error("network");}return original(...args);});
  expect((await call("/settle",b)).status).toBe(503);expect(sql.prepare("SELECT status FROM store_orders").get().status).toBe("reviewed");expect((await call("/settle",b)).status).toBe(200);expect((await call("/settle",b)).status).toBe(200);expect(sql.prepare("SELECT count(*) AS n FROM store_order_batches").get().n).toBe(1);
 });
 it("取消ERP結果登記；舊結果不明紀錄不能重產或更正",async()=>{await settled();sql.prepare("UPDATE store_orders SET status='import_unknown'").run();expect((await call("/orders/test-order-001/result",{expectedVersion:2,status:"import_failed",reason:"舊流程"},HQ)).status).toBe(410);expect((await call("/orders/test-order-001/export",{expectedVersion:2,mode:"test"},HQ)).status).toBe(409);expect((await call("/orders/test-order-001/correct",{expectedVersion:2,order:order(),reason:"更正"},HQ)).status).toBe(409);});
 it("HQ更正保留原版；沒有原因或狀態不明不可更正",async()=>{await settled();const o=(await call("/orders/test-order-001",undefined,HQ)).body.order;const before=files.size;expect((await call("/orders/test-order-001/correct",{expectedVersion:2,order:o,reason:"",operationId:crypto.randomUUID()},HQ)).status).toBe(409);o.items[0].quantity=3;o.paperTotal=350;o.payments.現金=350;expect((await call("/orders/test-order-001/correct",{expectedVersion:2,order:o,reason:"更正數量",operationId:crypto.randomUUID()},HQ)).status).toBe(200);expect(files.size).toBe(before+1);expect((await call("/orders/test-order-001",undefined,HQ)).body.order.items[0].quantity).toBe(3);});
 it("總部更正單號也維持跨訂單唯一性",async()=>{await settled();file("source-file-002",config.stores.R00.pendingFolderId,"second-synthetic-image","image/png");await call("/sources",{storeCode:"R00",fileId:"source-file-002"});const second=order();second.id="test-order-002";second.paperNumber="SYNTH-002";second.sources[0].fileId="source-file-002";expect((await save(second)).status).toBe(200);const first=(await call("/orders/test-order-001",undefined,HQ)).body.order;first.paperNumber="SYNTH-002";expect((await call("/orders/test-order-001/correct",{expectedVersion:2,order:first,reason:"更正單號",operationId:crypto.randomUUID()},HQ)).status).toBe(409);first.paperNumber="SYNTH-003";expect((await call("/orders/test-order-001/correct",{expectedVersion:2,order:first,reason:"依紙本修正",operationId:crypto.randomUUID()},HQ)).status).toBe(200);});
 it("無單日需明確勾選，真正有單不能選空清單結算",async()=>{const b={storeCode:"R00",businessDate:"2026-10-23",orders:[],confirmed:true,operationId:crypto.randomUUID()};expect((await call("/settle",b)).status).toBe(400);expect((await call("/settle",{...b,noOrders:true})).status).toBe(200);});
});
describe("Drive真正權限判斷邏輯",()=>{
 it("公開、全網域、群組或其他門市的直接權限都拒絕",async()=>{
  OrderDrive.prototype.checkPermissions.mockRestore();const d=new OrderDrive(env,config);
  for(const bad of [{type:"anyone"},{type:"domain"},{type:"group",emailAddress:"g@siangapato.com.tw"},{type:"user",emailAddress:OTHER}]){vi.spyOn(d,"request").mockResolvedValue({permissions:[{type:"user",emailAddress:HQ},bad]});await expect(d.checkPermissions("settled-folder-001",[HQ])).rejects.toThrow(/未授權|群組/);}
  d.request=vi.fn(async()=>({permissions:[{type:"user",emailAddress:HQ},{type:"user",emailAddress:"service@test.gserviceaccount.com"}]}));await expect(d.checkPermissions("settled-folder-001",[HQ])).resolves.toBeUndefined();
 });
});

it("後端阻擋跨列總價重複及未確認分配，不能繞過前台",async()=>{await register();const o=order();o.items[0].priceGroupId="shared-test";o.items[1].priceGroupId="shared-test";o.priceGroups=[{id:"shared-test",amount:250,allocationConfirmed:false}];expect((await save(o)).status).toBe(400);o.priceGroups[0].allocationConfirmed=true;expect((await save(o)).status).toBe(200);});

it("後端要求完整單表頭確認，不能只在前台勾選逐欄覆核",async()=>{await register();const o=order();o.headerRecognition={confirmed:false,rawDate:"115/10/23",pageNumber:1,uncertainFields:[],synthetic:true};expect((await save(o)).status).toBe(400);o.headerRecognition.confirmed=true;expect((await save(o)).status).toBe(200);});

it("後端接受整組總價且不拆各列價格，金額不符或重複單價仍阻擋",async()=>{await register();const o=order();o.items.forEach(i=>{i.priceGroupId="bundle-total";i.unitPrice="";});o.priceGroups=[{id:"bundle-total",amount:251,pricingMode:"total_only",totalConfirmed:true}];expect((await save(o)).status).toBe(400);o.priceGroups[0].amount=250;o.items[0].unitPrice=0;expect((await save(o)).status).toBe(400);o.items[0].unitPrice="";expect((await save(o)).status).toBe(200);});

// Exercise the same API with actual signed guest cookies, not a mocked guest actor.
async function guestLogin(){const {issueGuestInvite,redeemGuestInvite}=await import('../worker/src/store-order-guests');env.STORE_ORDERS_GUEST_KEY='synthetic-guest-secret-64-characters-aaaaaaaaaaaaaaaaaaaa';const invite=await issueGuestInvite(env,HQ,'R00');const result=await redeemGuestInvite(new Request('https://siangstock.com/api/store-orders-guest/redeem',{headers:{'CF-Connecting-IP':'192.0.2.1'}}),env,{code:invite.code},['R00']);return result.setCookie.split(';')[0];}
async function guestCall(cookie,path,body){const r=await storeOrdersRoute(new Request('https://siangstock.com/api/store-orders-guest'+path,{method:body===undefined?'GET':'POST',headers:{Cookie:cookie,Origin:'https://siangstock.com','Content-Type':'application/json','X-Store-Orders-Version':VERSION},...(body===undefined?{}:{body:JSON.stringify(body)})}),env);return {status:r.status,body:await r.json()};}
it('訪客Cookie只授權自己的單據與原圖，不能列出同店他人資料或結算',async()=>{const cookie=await guestLogin(),who=(await guestCall(cookie,'/session')).body;expect(who.guest).toBe(true);expect(who.googleClientId).toBeUndefined();expect(who.masterFolderId).toBeUndefined();expect(who.stores.R00.pendingFolderId).toBeUndefined();await register();await save();expect((await guestCall(cookie,'/orders/test-order-001')).status).toBe(403);expect((await guestCall(cookie,'/queue?store=R00&date=2026-10-23')).body.orders).toHaveLength(0);expect((await guestCall(cookie,'/scan?store=R00')).body.files).toHaveLength(0);expect((await guestCall(cookie,'/sources',{storeCode:'R00',fileId:'source-file-001'})).status).toBe(403);expect((await guestCall(cookie,'/settle',{storeCode:'R00'})).status).toBe(403);expect((await guestCall(cookie,'/guest-invites')).status).toBe(403);expect((await guestCall(cookie,'/queue?store=R01&date=2026-10-23')).status).toBe(403);});
it('訪客可以保存自己來源的覆核，另一訪客不能讀取或覆寫',async()=>{const a=await guestLogin(),b=await guestLogin(),who=(await guestCall(a,'/session')).body;file('guest-source-001',config.stores.R00.pendingFolderId,'guest-image','image/png',{appProperties:{soActor:who.email}});expect((await guestCall(a,'/sources',{storeCode:'R00',fileId:'guest-source-001'})).status).toBe(200);const o=order();o.sources[0].fileId='guest-source-001';expect((await guestCall(a,'/orders',{order:o,expectedVersion:0,operationId:crypto.randomUUID()})).status).toBe(200);expect((await guestCall(a,'/orders/'+o.id)).body.order.items).toHaveLength(2);expect((await guestCall(b,'/orders/'+o.id)).status).toBe(403);expect((await guestCall(b,'/orders',{order:{...o,version:1},expectedVersion:1,operationId:crypto.randomUUID()})).status).toBe(403);});
it('商品查詢僅總部能發布且禁止成本等額外欄位，訪客不取得成本',async()=>{env.STORE_ORDERS_CONFIG=JSON.stringify({...config,catalogFolderId:'catalog-folder-001'});const cookie=await guestLogin(),data={version:'synthetic-v1',records:[{sku:'SYNTH01',name:'合成床包',color:'白',colorCode:'01',size:'5尺',sizeCode:'05',discontinued:false}]};expect((await guestCall(cookie,'/catalog',data)).status).toBe(403);expect((await call('/catalog',{...data,records:[{...data.records[0],cost:100}]},HQ)).status).toBe(400);expect((await call('/catalog',data,HQ)).status).toBe(200);const read=await guestCall(cookie,'/catalog');expect(read.body).toEqual(data);expect(JSON.stringify(read.body)).not.toContain('cost');expect((await call('/catalog',{...data,records:[{...data.records[0],name:'改名'}]},HQ)).status).toBe(409);});
