async function hqRegistry(){
 sql.exec(readFileSync('worker/migrations/0046_store_order_hq_access.sql','utf8'));
 sql.prepare('UPDATE store_order_hq_access SET emails=?,version=1,updated_by=? WHERE id=1').run(JSON.stringify(['hq2@siangapato.com.tw']),'siang01@siangapato.com.tw');
 env.STORE_ORDERS_CONFIG=JSON.stringify({...config,storageType:'company_account',rootFolderId:'company-root-001',ownerEmail:'siang01@siangapato.com.tw',hqEmails:['siang01@siangapato.com.tw']});
 for(const f of files.values())delete f.driveId;
}
async function updateRoles(body,email='siang01@siangapato.com.tw',extra={}){
 const r=await storeOrdersRoute(new Request('https://siangstock.com/api/store-orders/hq-access',{method:'PUT',headers:{Origin:'https://siangstock.com','Content-Type':'application/json','X-Store-Orders-Version':VERSION,'X-Test-Email':email,...extra},body:JSON.stringify(body)}),env);return {status:r.status,body:await r.json()};
}
