it('最高權限增減即時生效，版本衝突不覆寫，原子歷史保留舊名單',async()=>{await hqRegistry();const b={emails:['hq3@siangapato.com.tw'],expectedVersion:1};expect((await updateRoles(b)).status).toBe(200);expect((await call('/session',undefined,'hq2@siangapato.com.tw')).status).toBe(403);expect((await call('/session',undefined,'hq3@siangapato.com.tw')).body.role).toBe('hq');expect((await updateRoles({emails:[],expectedVersion:1})).status).toBe(409);expect(JSON.parse(sql.prepare('SELECT emails FROM store_order_hq_access WHERE id=1').get().emails)).toEqual(b.emails);expect(sql.prepare('SELECT * FROM store_order_hq_access_history WHERE version=2').get()).toMatchObject({previous_emails:'["hq2@siangapato.com.tw"]',updated_by:'siang01@siangapato.com.tw'});expect((await updateRoles({emails:[],expectedVersion:2})).status).toBe(200);expect((await call('/session',undefined,'siang01@siangapato.com.tw')).status).toBe(200);});
it('外部email、重複、門市角色、最高權限移除企圖、舊版本及跨來源不能寫入名單',async()=>{await hqRegistry();for(const emails of [['outside@gmail.com'],['HQ2@siangapato.com.tw','hq2@siangapato.com.tw'],[EMAIL],['siang01@siangapato.com.tw']])expect((await updateRoles({emails,expectedVersion:1})).status).toBe(400);expect((await updateRoles({emails:[],expectedVersion:1},undefined,{'X-Store-Orders-Version':'old'})).status).toBe(409);expect((await updateRoles({emails:[],expectedVersion:1},undefined,{Origin:'https://evil.example'})).status).toBe(403);expect((await call('/hq-access',undefined,'siang01@siangapato.com.tw')).body.version).toBe(1);});
