async function twoOrderBatch(){
 await register();await save();file('source-file-002',config.stores.R00.pendingFolderId,'second-image','image/png');await call('/sources',{storeCode:'R00',fileId:'source-file-002'});
 const o=order();o.id='test-order-002';o.paperNumber='SYNTH-002';o.sources[0].fileId='source-file-002';expect((await save(o)).status).toBe(200);
 const result=await call('/settle',{storeCode:'R00',businessDate:'2026-10-23',orders:[{id:'test-order-001',version:1},{id:o.id,version:1}],confirmed:true,operationId:crypto.randomUUID()});expect(result.status).toBe(200);return result.body.batchId;
}
async function batchBody(id){const r=await call('/batches/'+id,undefined,HQ);expect(r.status).toBe(200);return {view:r.body,body:{orders:r.body.orders.map(o=>({id:o.id,version:o.version}))}};}
it('整批摘要僅總部可讀，兩單件數金額付款守恆，無需開啟單筆',async()=>{const id=await twoOrderBatch();expect((await call('/batches/'+id)).status).toBe(403);const {view}=await batchBody(id);expect(view.summary).toMatchObject({orders:2,rows:4,quantity:6,amountCents:50000,paidCents:50000});expect(view.orders.map(o=>o.paperNumber)).toEqual(['SYNTH-001','SYNTH-002']);expect(view.downloaded).toBe(false);expect((await call('/batches/missing-batch-000',undefined,HQ)).status).toBe(404);});
it('批次匯出保留正式開關，未開放不更新任何一筆',async()=>{const id=await twoOrderBatch(),{body}=await batchBody(id);expect((await call('/batches/'+id+'/export',body,HQ)).status).toBe(403);expect(sql.prepare("SELECT COUNT(*) n FROM store_orders WHERE status='settled'").get().n).toBe(2);});
it('整批一次產檔；少一單、舊版本、重按或未確認補下載都阻擋',async()=>{const id=await twoOrderBatch(),{body}=await batchBody(id);env.STORE_ORDERS_PRODUCTION_EXPORT='approved-20261030';expect((await call('/batches/'+id+'/export',{orders:body.orders.slice(0,1)},HQ)).status).toBe(409);const stale=structuredClone(body);stale.orders[1].version--;expect((await call('/batches/'+id+'/export',stale,HQ)).status).toBe(409);const first=await call('/batches/'+id+'/export',body,HQ);expect(first.status).toBe(200);expect(first.body.versions.map(o=>o.version)).toEqual([3,3]);expect(sql.prepare("SELECT COUNT(*) n FROM store_orders WHERE status='exported'").get().n).toBe(2);expect((await call('/batches/'+id+'/export',body,HQ)).status).toBe(409);const next=await batchBody(id);expect(next.view.downloaded).toBe(true);expect((await call('/batches/'+id+'/export',next.body,HQ)).status).toBe(409);expect((await call('/batches/'+id+'/export',{...next.body,redownloadConfirmed:true},HQ)).status).toBe(200);expect(sql.prepare('SELECT version FROM store_orders').all().map(o=>o.version)).toEqual([3,3]);expect(sql.prepare("SELECT COUNT(*) n FROM store_order_events WHERE event='batch_pos_exported'").get().n).toBe(1);});
it('產檔提交時任一單被更正，SQLite原子判斷阻擋整批而非部分成功',async()=>{const id=await twoOrderBatch(),{body}=await batchBody(id);env.STORE_ORDERS_PRODUCTION_EXPORT='approved-20261030';const original=env.DB.batch.bind(env.DB);env.DB.batch=async statements=>{sql.prepare("UPDATE store_orders SET version=version+1 WHERE id='test-order-002'").run();return original(statements);};expect((await call('/batches/'+id+'/export',body,HQ)).status).toBe(409);expect(sql.prepare("SELECT COUNT(*) n FROM store_orders WHERE status='settled'").get().n).toBe(2);expect(sql.prepare("SELECT COUNT(*) n FROM store_order_events WHERE event='batch_pos_exported'").get().n).toBe(0);});
it('交接未完成、部分舊產檔、舊ERP結果與已回收批次皆不允許整批產檔',async()=>{const id=await twoOrderBatch();sql.prepare("UPDATE store_order_batches SET status='preparing' WHERE id=?").run(id);expect((await call('/batches/'+id,undefined,HQ)).status).toBe(409);sql.prepare("UPDATE store_order_batches SET status='settled' WHERE id=?").run(id);for(const status of ['exported','import_unknown','erp_created']){sql.prepare("UPDATE store_orders SET status=? WHERE id='test-order-002'").run(status);expect((await call('/batches/'+id,undefined,HQ)).status).toBe(409);}sql.prepare("UPDATE store_orders SET status='settled',recycled_at='2026-11-01' WHERE id='test-order-002'").run();expect((await call('/batches/'+id,undefined,HQ)).status).toBe(410);});
it('無單批次可以查看，但不能下載空POS',async()=>{const r=await call('/settle',{storeCode:'R00',businessDate:'2026-10-23',orders:[],confirmed:true,noOrders:true,operationId:crypto.randomUUID()});const id=r.body.batchId,{view,body}=await batchBody(id);expect(view.summary.orders).toBe(0);env.STORE_ORDERS_PRODUCTION_EXPORT='approved-20261030';expect((await call('/batches/'+id+'/export',body,HQ)).status).toBe(409);});

it('產檔即完成；補下載不重設時間，90天後只移受限回收區',async()=>{const id=await twoOrderBatch(),{body}=await batchBody(id);env.STORE_ORDERS_PRODUCTION_EXPORT='approved-20261030';expect((await call('/batches/'+id+'/export',body,HQ)).status).toBe(200);const before=sql.prepare('SELECT id,updated_at FROM store_orders ORDER BY id').all();const next=await batchBody(id);await call('/batches/'+id+'/export',{...next.body,redownloadConfirmed:true},HQ);expect(sql.prepare('SELECT id,updated_at FROM store_orders ORDER BY id').all()).toEqual(before);expect((await call('/retention',{},HQ)).body.recycledBatches).toBe(0);sql.prepare('UPDATE store_orders SET updated_at=?').run(new Date(Date.now()-91*86400000).toISOString());expect((await call('/retention',{},HQ)).body).toEqual({recycledBatches:1,permanentlyDeleted:false});expect(sql.prepare('SELECT COUNT(*) n FROM store_orders WHERE recycled_at IS NOT NULL').get().n).toBe(2);});
it('已產檔的舊日期單據不再列為30天未完成待辦',async()=>{await settled();sql.prepare("UPDATE store_orders SET status='exported',business_date='2020-01-01'").run();expect((await call('/attention',undefined,HQ)).body.orders).toHaveLength(0);});
it('其中一單快照無效時整批拒絕；稽核寫入失敗也回滾所有產檔狀態',async()=>{const id=await twoOrderBatch(),{body}=await batchBody(id);env.STORE_ORDERS_PRODUCTION_EXPORT='approved-20261030';const row=sql.prepare("SELECT drive_id FROM store_orders WHERE id='test-order-002'").get();const original=files.get(row.drive_id).content;files.get(row.drive_id).content={...original,paperTotal:999};expect((await call('/batches/'+id+'/export',body,HQ)).status).toBe(409);expect(sql.prepare("SELECT COUNT(*) n FROM store_orders WHERE status='settled'").get().n).toBe(2);files.get(row.drive_id).content=original;const prepare=env.DB.prepare.bind(env.DB);env.DB.prepare=query=>{const stmt=prepare(query);if(query.includes('SELECT ?,?,?,?,? WHERE changes()>0'))stmt.run=async()=>{throw Error('synthetic audit failure');};return stmt;};expect((await call('/batches/'+id+'/export',body,HQ)).status).toBe(503);expect(sql.prepare("SELECT COUNT(*) n FROM store_orders WHERE status='settled'").get().n).toBe(2);});
it('補交另建批次，下載其中一批不混入其他批次或取消單',async()=>{const first=await twoOrderBatch();file('source-file-003',config.stores.R00.pendingFolderId,'third-image','image/png');await call('/sources',{storeCode:'R00',fileId:'source-file-003'});const o=order();o.id='test-order-003';o.paperNumber='SYNTH-003';o.sources[0].fileId='source-file-003';expect((await save(o)).status).toBe(200);const second=await call('/settle',{storeCode:'R00',businessDate:'2026-10-23',orders:[{id:o.id,version:1}],confirmed:true,operationId:crypto.randomUUID()});expect(second.status).toBe(200);expect((await batchBody(first)).view.orders).toHaveLength(2);const next=await batchBody(second.body.batchId);expect(next.view.orders.map(o=>o.id)).toEqual([o.id]);sql.prepare("UPDATE store_orders SET status='cancelled' WHERE id='test-order-002'").run();const batch=await batchBody(first);expect(batch.view.orders).toHaveLength(1);expect(batch.view.excludedCount).toBe(1);env.STORE_ORDERS_PRODUCTION_EXPORT='approved-20261030';expect((await call('/batches/'+first+'/export',batch.body,HQ)).status).toBe(200);expect(sql.prepare("SELECT status FROM store_orders WHERE id='test-order-003'").get().status).toBe('settled');});
